126	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
127	    @Override
128	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
129	        HttpHeaders headers = new HttpHeaders();
130	        String idempotencyKey = this.request.getHeader(IDEMPOTENCY_KEY_HEADER);
131	        Integer existingId = this.idempotencyKeyRegistry.findOwnerId(idempotencyKey);
132	        if (existingId != null) {
133	            Owner existing = this.clinicService.findOwnerById(existingId);
134	            if (existing != null) {
135	                return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
136	            }
137	        }
138	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
139	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
140	        owner.setTelephone(normalizedTelephone);
141	        owner.setEmail(normalizeEmail(owner.getEmail()));
142	        applyAddress(owner);
143	        validatePostcode(owner.getCity(), owner.getPostcode());
144	        LocalDate effectiveRegistrationDate = owner.getRegistrationDate();
145	        if (effectiveRegistrationDate == null) {
146	            effectiveRegistrationDate = LocalDate.now();
147	        } else if (effectiveRegistrationDate.isAfter(LocalDate.now())) {
148	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
149	                "registrationDate must not be later than the current server date");
150	        }
151	        effectiveRegistrationDate = rollToBusinessDay(effectiveRegistrationDate);
152	        owner.setRegistrationDate(effectiveRegistrationDate);
153	        if (countOwnersRegisteredOn(effectiveRegistrationDate) >= DAILY_CREATE_LIMIT) {
154	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
155	                "the maximum number of owners that may be created today has been reached");
156	        }
157	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
158	        // The household id is deterministic (derived from the last name and postcode), so every
159	        // owner is keyed to its household automatically, regardless of creation order.
160	        this.clinicService.assignHousehold(owner);
161	        boolean householdInUse = this.clinicService.isHouseholdInUse(owner.getHouseholdId(), null);
162	        if (householdInUse && !sharesHousehold) {
163	            throw new ResponseStatusException(HttpStatus.CONFLICT,
164	                "an owner in the same household already exists");
165	        }
166	        if (isIdentityKeyInUse(ownerMapper.toIdentityKey(owner), null)) {
167	            throw new ResponseStatusException(HttpStatus.CONFLICT,
168	                "an owner with the same identity already exists");
169	        }
170	        if (countOwnersInCity(owner.getCity()) >= CITY_CAPACITY) {
171	            throw new ResponseStatusException(HttpStatus.CONFLICT,
172	                "city has reached its maximum number of owners");
173	        }
174	        owner.setCustomerCode(customerCodeFor(owner));
175	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
176	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
177	        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()) + 1);
178	        owner.setBulkSignupWarning(
179	            countOwnersRegisteredOn(effectiveRegistrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
180	        // A declared household member (one created with 'sharesHousehold' that joins an existing
181	        // household) is not a suspected duplicate, so it is never flagged as a possible duplicate.
182	        boolean declaredHouseholdMember = sharesHousehold && householdInUse;
183	        Owner softDuplicate = declaredHouseholdMember ? null : findPossibleDuplicate(owner);
184	        owner.setPossibleDuplicate(softDuplicate != null);
185	        owner.setPossibleDuplicateOf(softDuplicate == null ? null : softDuplicate.getId());
186	        this.clinicService.saveOwner(owner);
187	        this.idempotencyKeyRegistry.record(idempotencyKey, owner.getId());
188	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
189	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
190	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
191	            ownerDto.getMembershipLevel(), ownerDto.getMembershipNumber());
192	        headers.setLocation(UriComponentsBuilder.newInstance()
193	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
194	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
195	    }
