205	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
206	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
207	        applyAddress(currentOwner);
208	        currentOwner.setCity(ownerFieldsDto.getCity());
209	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
210	        currentOwner.setLastName(ownerFieldsDto.getLastName());
211	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
212	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
213	        this.clinicService.saveOwner(currentOwner);
